Here's a C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    string wordToCount;  // Specific word to count
    int wordCount = 0;   // Word count variable

    cout << "Enter the word you want to count: ";
    cin >> wordToCount;  // Get the word to count from user

    map<string, int> wordMap;  // Map to store word and its count

    // Open the text file for reading
    ifstream inputFile("your_text_file.txt");
    if (inputFile.is_open()) {
        string line;

        // Read file line by line
        while (getline(inputFile, line)) {
            // Convert the line to lowercase for case-insensitive word counting
            transform(line.begin(), line.end(), line.begin(), ::tolower);

            // Find the word in the line and increment the count if found
            size_t pos = line.find(wordToCount);
            while (pos != string::npos) {
                wordCount++;
                pos = line.find(wordToCount, pos + wordToCount.length());
            }

            // Add the word and its count to the map
            wordMap[wordToCount] = wordCount;
        }

        inputFile.close();
    }
    else {
        cout << "Error opening file" << endl;
        return 1;
    }

    // Print the word count
    cout << "The word '" << wordToCount << "' appears " << wordMap[wordToCount] << " times in the file." << endl;

    return 0;
}
```

Replace `your_text_file.txt` with the actual name of the text file you want to analyze. This program will read the file line by line, convert the lines to lowercase for case-insensitive word counting, and keep track of the occurrences of the specified word. Finally, it prints the word count to the console.

To find the common elements in two arrays without using any extra data structures, you can use a simple approach that compares each element in the first array with each element in the second array. If a match is found, the element is considered a common element. The following C++ program demonstrates this approach:

```cpp
#include <iostream>
using namespace std;

int main() {
    int arr1[] = {2, 4, 6, 8, 10, 12};
    int arr2[] = {4, 6, 8, 10, 12, 14};
    int n1 = sizeof(arr1) / sizeof(arr1[0]);
    int n2 = sizeof(arr2) / sizeof(arr2[0]);

    // Iterate through both arrays
    for (int i = 0; i < n1; i++) {
        for (int j = 0; j < n2; j++) {
            if (arr1[i] == arr2[j]) {
                // Print common element
                cout << arr1[i] << " ";
                break;
            }
        }
    }

    return 0;
}
```

This program iterates through both arrays, comparing each element of `arr1` with each element of `arr2`. If a match is found, the common element is printed and the loop is broken to avoid printing duplicates. The program uses `sizeof` to determine the size of both arrays.
